                                                            <Button x:Name="Btn_BootRecovery" Grid.Column="1" Content="BOOT TO RECOVERY" Background="#333" Foreground="#FF9955" FontWeight="Bold" Height="40" Margin="5,5,0,5" ToolTip="Restarts PC into Advanced Startup Options."/>
